 *
 * @return mixed
 */
public static function extractSheetTitle($range, $returnRange = false)
{
    if (empty($range)) {
        return $returnRange ? [null, null] : null;
    }

    // Sheet title included?
    if (($sep = strrpos($range, '!')) === false) {
        return $returnRange ? ['', $range] : '';
    }

